class Solution {
public:
    TreeNode* buildTree(vector<int>& inorder, vector<int>& postorder) {
        for (int i = 0; i < (int)inorder.size(); i++) pos[inorder[i]] = i;
        return build(0, (int)inorder.size() - 1, (int)postorder.size() - 1, postorder);
    }

private:
    unordered_map<int, int> pos;

    TreeNode* build(int l, int r, int pr, vector<int>& postorder) {
        if (l > r) return nullptr;
        TreeNode* root = new TreeNode(postorder[pr]);
        int k = pos[root->val];
        root->left = build(l, k - 1, pr - (r - k) - 1, postorder);
        root->right = build(k + 1, r, pr - 1, postorder);
        return root;
    }
};

