    TreeNode* root = new TreeNode(postorder[pr]);
    int k = pos[root->val];
    root->left = go(l, k - 1, pr - (r - k) - 1, postorder);
    root->right = go(k + 1, r, pr - 1, postorder);
    return root;
}

string serialize(TreeNode* root) {
    if (!root) return "[]";
    vector<string> parts;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        TreeNode* node = q.front();
        q.pop();
        if (!node) {
            parts.push_back("null");
            continue;
        }
        parts.push_back(to_string(node->val));
        q.push(node->left);
        q.push(node->right);
    }
    while (!parts.empty() && parts.back() == "null") parts.pop_back();
    string res = "[";
    for (size_t i = 0; i < parts.size(); i++) {
        if (i) res += ",";
        res += parts[i];
    }
    return res + "]";
}

